use clap::{Arg, App, SubCommand, ArgMatches};
use serde::{Deserialize, Serialize};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, exit};
use std::collections::BTreeMap;
use std::io::Write;

#[derive(Debug, Serialize, Deserialize, Clone)]
struct Script {
    command: String,
    #[serde(default)]
    description: Option<String>,
    #[serde(default)]
    tags: Vec<String>,
}

#[derive(Debug, Serialize, Deserialize)]
struct Config {
    scripts: BTreeMap<String, Script>,
    #[serde(default)]
    default: toml::map::Map<String, toml::Value>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            scripts: BTreeMap::new(),
            default: toml::map::Map::new(),
        }
    }
}

fn find_config_file() -> Result<PathBuf, String> {
    // Check PIER_CONFIG_PATH environment variable
    if let Ok(path) = std::env::var("PIER_CONFIG_PATH") {
        if !path.is_empty() {
            let p = PathBuf::from(path);
            if p.exists() {
                return Ok(p);
            }
        }
    }

    // Check pier.toml in current directory
    let cwd = std::env::current_dir().ok();
    if let Some(cwd) = cwd {
        let p = cwd.join("pier.toml");
        if p.exists() {
            return Ok(p);
        }
    }

    // Check XDG_CONFIG_HOME
    if let Ok(xdg_config) = std::env::var("XDG_CONFIG_HOME") {
        if !xdg_config.is_empty() {
            let xdg_path = PathBuf::from(&xdg_config);

            let p = xdg_path.join("pier").join("config.toml");
            if p.exists() {
                return Ok(p);
            }

            let p = xdg_path.join("pier").join("config");
            if p.exists() {
                return Ok(p);
            }

            let p = xdg_path.join("pier.toml");
            if p.exists() {
                return Ok(p);
            }
        }
    }

    // Check $HOME/.config/pier (default XDG location)
    if let Some(home) = dirs::home_dir() {
        let xdg_default = home.join(".config");

        let p = xdg_default.join("pier").join("config.toml");
        if p.exists() {
            return Ok(p);
        }

        let p = xdg_default.join("pier").join("config");
        if p.exists() {
            return Ok(p);
        }

        let p = xdg_default.join("pier.toml");
        if p.exists() {
            return Ok(p);
        }

        // Check $HOME/.pier.toml
        let p = home.join(".pier.toml");
        if p.exists() {
            return Ok(p);
        }

        // Check $HOME/.pier
        let p = home.join(".pier");
        if p.exists() {
            return Ok(p);
        }
    }

    Err("No default config file found. See help for more info.".to_string())
}

fn load_config(config_path: &Path) -> Result<Config, String> {
    let content = fs::read_to_string(config_path)
        .map_err(|e| format!("Failed to read config: {}", e))?;
    toml::from_str(&content)
        .map_err(|e| format!("Failed to parse config: {}", e))
}

fn save_config(config_path: &Path, config: &Config) -> Result<(), String> {
    let content = toml::to_string_pretty(config)
        .map_err(|e| format!("Failed to serialize config: {}", e))?;
    fs::write(config_path, content)
        .map_err(|e| format!("Failed to write config: {}", e))
}

fn main() {
    let app = App::new("pier")
        .version("0.1.6")
        .about("A simple script management CLI")
        .author("Benjamin Scholtz, Isak Johansson")
        .arg(Arg::with_name("config-file")
            .short("c")
            .long("config-file")
            .help("Sets a custom config file.\n\nDEFAULT PATH is otherwise determined in this order:\n\n- $PIER_CONFIG_PATH (environment variable if set)\n\n- pier.toml (in the current directory)\n\n- $XDG_CONFIG_HOME/pier/config.toml\n\n- $XDG_CONFIG_HOME/pier/config\n\n- $XDG_CONFIG_HOME/pier.toml\n\n- $HOME/.pier.toml\n\n- $HOME/.pier")
            .takes_value(true)
            .value_name("path")
            .env("PIER_CONFIG_PATH"))
        .arg(Arg::with_name("verbose")
            .short("v")
            .long("verbose")
            .help("The level of verbosity"))
        .arg(Arg::with_name("alias")
            .help("The alias or name for the script.")
            .index(1))
        .arg(Arg::with_name("args")
            .help("The positional arguments to send to script.")
            .multiple(true)
            .index(2))
        .subcommand(SubCommand::with_name("add")
            .about("Add a new script to config.")
            .arg(Arg::with_name("alias")
                .short("a")
                .long("alias")
                .help("The alias or name for the script.")
                .required(true)
                .takes_value(true))
            .arg(Arg::with_name("description")
                .short("d")
                .long("description")
                .help("The description for the script.")
                .takes_value(true))
            .arg(Arg::with_name("tags")
                .short("t")
                .long("tag")
                .help("Set which tags the script belongs to.")
                .multiple(true)
                .takes_value(true))
            .arg(Arg::with_name("force")
                .short("f")
                .long("force")
                .help("Allows to overwrite the existing script"))
            .arg(Arg::with_name("command")
                .help("The command/script content to be executed. If this argument is not found it will open your $EDITOR for you to enter the script into.")
                .index(1)))
        .subcommand(SubCommand::with_name("list")
            .alias("ls")
            .about("List scripts")
            .arg(Arg::with_name("list_aliases")
                .short("q")
                .long("list_aliases")
                .help("Only displays aliases of the scripts."))
            .arg(Arg::with_name("cmd_full")
                .short("l")
                .long("cmd_full")
                .help("Display the full command."))
            .arg(Arg::with_name("cmd_width")
                .short("c")
                .long("cmd_width")
                .help("The max number of characters to display from the command.")
                .takes_value(true)
                .value_name("cmd-width"))
            .arg(Arg::with_name("tags")
                .short("t")
                .long("tag")
                .help("Filter based on tags.")
                .multiple(true)
                .takes_value(true)))
        .subcommand(SubCommand::with_name("run")
            .about("Run a script matching alias.")
            .arg(Arg::with_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .index(1))
            .arg(Arg::with_name("args")
                .help("The positional arguments to send to script.")
                .multiple(true)
                .index(2)))
        .subcommand(SubCommand::with_name("show")
            .about("Show a script matching alias.")
            .arg(Arg::with_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .index(1)))
        .subcommand(SubCommand::with_name("remove")
            .alias("rm")
            .about("Remove a script matching alias.")
            .arg(Arg::with_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .index(1)))
        .subcommand(SubCommand::with_name("copy")
            .alias("cp")
            .about("Copy existing alias to the new one")
            .arg(Arg::with_name("from-alias")
                .help("The alias of the script that will be copied.")
                .required(true)
                .index(1))
            .arg(Arg::with_name("to-alias")
                .help("The new alias of the copy of the script.")
                .required(true)
                .index(2)))
        .subcommand(SubCommand::with_name("move")
            .alias("mv")
            .alias("rename")
            .about("Move/rename existing alias to the new one")
            .arg(Arg::with_name("from-alias")
                .help("The alias of the script that will be moved.")
                .required(true)
                .index(1))
            .arg(Arg::with_name("to-alias")
                .help("The new alias of the script.")
                .required(true)
                .index(2))
            .arg(Arg::with_name("force")
                .short("f")
                .long("force")
                .help("Allows to overwrite the existing script")))
        .subcommand(SubCommand::with_name("edit")
            .about("Edit a script matching alias.")
            .arg(Arg::with_name("alias")
                .help("The alias or name for the script.")
                .required(true)
                .index(1)))
        .subcommand(SubCommand::with_name("config-init")
            .alias("init")
            .about("Add a config file."));

    let matches = app.get_matches();

    // Get config file path
    let config_path = if let Some(path) = matches.value_of("config-file") {
        PathBuf::from(path)
    } else {
        match find_config_file() {
            Ok(path) => path,
            Err(e) => {
                println!("error: {}", e);
                exit(1);
            }
        }
    };

    match matches.subcommand() {
        ("add", Some(sub_m)) => cmd_add(&config_path, sub_m),
        ("list", Some(sub_m)) => cmd_list(&config_path, sub_m),
        ("run", Some(sub_m)) => cmd_run(&config_path, sub_m),
        ("show", Some(sub_m)) => cmd_show(&config_path, sub_m),
        ("remove", Some(sub_m)) => cmd_remove(&config_path, sub_m),
        ("copy", Some(sub_m)) => cmd_copy(&config_path, sub_m),
        ("move", Some(sub_m)) => cmd_move(&config_path, sub_m),
        ("edit", Some(sub_m)) => cmd_edit(&config_path, sub_m),
        ("config-init", Some(_)) => cmd_config_init(&config_path),
        ("help", Some(sub_m)) => {
            // Help is handled by clap
        },
        _ => {
            // Try to run as a script if it looks like a direct invocation
            if let Some(alias) = matches.value_of("alias") {
                let args: Vec<&str> = matches.values_of("args").unwrap_or_default().collect();
                cmd_run_direct(&config_path, alias, args);
            }
        }
    }
}

fn cmd_add(config_path: &Path, matches: &ArgMatches) {
    let alias = matches.value_of("alias").unwrap().to_string();
    let description = matches.value_of("description").map(|s| s.to_string());
    let tags: Vec<String> = matches.values_of("tags")
        .unwrap_or_default()
        .map(|s| s.to_string())
        .collect();

    let command = if let Some(cmd) = matches.value_of("command") {
        cmd.to_string()
    } else {
        // Open editor - for now just return error since we can't handle interactive editing
        println!("error: EditorError: Failed when trying to get input from editor Failed to open `vi` as a text editor or editor was terminated with errors.");
        exit(1);
    };

    let mut config = match load_config(config_path) {
        Ok(c) => c,
        Err(e) => {
            println!("error: {}", e);
            exit(1);
        }
    };

    if config.scripts.contains_key(&alias) && !matches.is_present("force") {
        println!("error: AliasAlreadyExists:  {}", alias);
        exit(1);
    }

    config.scripts.insert(alias.clone(), Script {
        command,
        description,
        tags,
    });

    if let Err(e) = save_config(config_path, &config) {
        println!("error: {}", e);
        exit(1);
    }

    println!("Added {}", alias);
}

fn cmd_list(config_path: &Path, matches: &ArgMatches) {
    let config = match load_config(config_path) {
        Ok(c) => c,
        Err(e) => {
            println!("error: {}", e);
            exit(1);
        }
    };

    let filter_tags: Vec<String> = matches.values_of("tags")
        .unwrap_or_default()
        .map(|s| s.to_string())
        .collect();

    let list_aliases = matches.is_present("list_aliases");
    let cmd_full = matches.is_present("cmd_full");
    let cmd_width: Option<usize> = matches.value_of("cmd_width")
        .and_then(|s| s.parse().ok());

    // Filter scripts
    let scripts: Vec<_> = config.scripts.iter()
        .filter(|(_, script)| {
            if filter_tags.is_empty() {
                true
            } else {
                filter_tags.iter().all(|tag| script.tags.contains(tag))
            }
        })
        .collect();

    if list_aliases {
        // Just list aliases
        for (alias, _) in scripts {
            println!("{}", alias);
        }
    } else {
        // Table view
        let mut rows = Vec::new();

        for (alias, script) in scripts {
            let tags_str = script.tags.join(", ");
            let cmd = if cmd_full {
                script.command.clone()
            } else if let Some(width) = cmd_width {
                if script.command.len() > width {
                    script.command[..width].to_string()
                } else {
                    script.command.clone()
                }
            } else {
                script.command.clone()
            };
            let desc = script.description.clone().unwrap_or_default();

            rows.push((alias.clone(), tags_str, cmd, desc));
        }

        if rows.is_empty() {
            return;
        }

        // Calculate column widths
        let mut alias_width = 5; // "Alias"
        let mut tags_width = 4;  // "Tags"
        let mut cmd_width = 7;   // "Command"
        let mut desc_width = 11; // "Description"

        for (alias, tags, cmd, desc) in &rows {
            alias_width = alias_width.max(alias.len());
            tags_width = tags_width.max(tags.len());
            cmd_width = cmd_width.max(cmd.len());
            desc_width = desc_width.max(desc.len());
        }

        // Print table
        let border = "≖".repeat(alias_width + tags_width + cmd_width + desc_width + 11); // 11 for separators
        println!("{}", border);

        // Header
        print!("⋮ {:<width1$} ⋮ {:<width2$} ⋮ {:<width3$} ⋮ {:<width4$} ⋮", 
            "Alias", "Tags", "Command", "Description",
            width1 = alias_width,
            width2 = tags_width,
            width3 = cmd_width,
            width4 = desc_width);
        println!();

        println!("{}", border);

        // Data rows
        for (alias, tags, cmd, desc) in rows {
            print!("⋮ {:<width1$} ⋮ {:<width2$} ⋮ {:<width3$} ⋮ {:<width4$} ⋮",
                alias, tags, cmd, desc,
                width1 = alias_width,
                width2 = tags_width,
                width3 = cmd_width,
                width4 = desc_width);
            println!();
        }

        println!("{}", border);
    }
}

fn cmd_run(config_path: &Path, matches: &ArgMatches) {
    let alias = matches.value_of("alias").unwrap();
    let args: Vec<&str> = matches.values_of("args").unwrap_or_default().collect();

    let config = match load_config(config_path) {
        Ok(c) => c,
        Err(e) => {
            println!("error: {}", e);
            exit(1);
        }
    };

    if let Some(script) = config.scripts.get(alias) {
        // Execute the script command with the provided arguments
        let mut cmd = Command::new("sh");
        cmd.arg("-c");

        // Build the full command with arguments
        let mut full_cmd = script.command.clone();
        for arg in &args {
            // Pass arguments as shell variables or by appending
            full_cmd.push(' ');
            full_cmd.push_str(arg);
        }

        cmd.arg(&full_cmd);

        let status = cmd.status();
        match status {
            Ok(status) => {
                if !status.success() {
                    exit(status.code().unwrap_or(1));
                }
            }
            Err(e) => {
                println!("error: Failed to execute script: {}", e);
                exit(1);
            }
        }
    } else {
        println!("error: AliasNotFound: No script found by alias {}", alias);
        exit(1);
    }
}

fn cmd_run_direct(config_path: &Path, alias: &str, args: Vec<&str>) {
    let config = match load_config(config_path) {
        Ok(c) => c,
        Err(e) => {
            println!("error: {}", e);
            exit(1);
        }
    };

    if let Some(script) = config.scripts.get(alias) {
        let mut cmd = Command::new("sh");
        cmd.arg("-c");

        let mut full_cmd = script.command.clone();
        for arg in &args {
            full_cmd.push(' ');
            full_cmd.push_str(arg);
        }

        cmd.arg(&full_cmd);

        let status = cmd.status();
        match status {
            Ok(status) => {
                if !status.success() {
                    exit(status.code().unwrap_or(1));
                }
            }
            Err(e) => {
                println!("error: Failed to execute script: {}", e);
                exit(1);
            }
        }
    } else {
        println!("error: AliasNotFound: No script found by alias {}", alias);
        exit(1);
    }
}

fn cmd_show(config_path: &Path, matches: &ArgMatches) {
    let alias = matches.value_of("alias").unwrap();

    let config = match load_config(config_path) {
        Ok(c) => c,
        Err(e) => {
            println!("error: {}", e);
            exit(1);
        }
    };

    if let Some(script) = config.scripts.get(alias) {
        println!("{}", script.command);
    } else {
        println!("error: AliasNotFound: No script found by alias {}", alias);
        exit(1);
    }
}

fn cmd_remove(config_path: &Path, matches: &ArgMatches) {
    let alias = matches.value_of("alias").unwrap().to_string();

    let mut config = match load_config(config_path) {
        Ok(c) => c,
        Err(e) => {
            println!("error: {}", e);
            exit(1);
        }
    };

    if config.scripts.remove(&alias).is_some() {
        if let Err(e) = save_config(config_path, &config) {
            println!("error: {}", e);
            exit(1);
        }
        println!("Removed {}", alias);
    } else {
        println!("error: AliasNotFound: No script found by alias {}", alias);
        exit(1);
    }
}

fn cmd_copy(config_path: &Path, matches: &ArgMatches) {
    let from_alias = matches.value_of("from-alias").unwrap().to_string();
    let to_alias = matches.value_of("to-alias").unwrap().to_string();

    let mut config = match load_config(config_path) {
        Ok(c) => c,
        Err(e) => {
            println!("error: {}", e);
            exit(1);
        }
    };

    if let Some(script) = config.scripts.get(&from_alias) {
        let new_script = script.clone();
        config.scripts.insert(to_alias.clone(), new_script);

        if let Err(e) = save_config(config_path, &config) {
            println!("error: {}", e);
            exit(1);
        }
        println!("Copy from alias {} to new alias {}", from_alias, to_alias);
    } else {
        println!("error: AliasNotFound: No script found by alias {}", from_alias);
        exit(1);
    }
}

fn cmd_move(config_path: &Path, matches: &ArgMatches) {
    let from_alias = matches.value_of("from-alias").unwrap().to_string();
    let to_alias = matches.value_of("to-alias").unwrap().to_string();
    let force = matches.is_present("force");

    let mut config = match load_config(config_path) {
        Ok(c) => c,
        Err(e) => {
            println!("error: {}", e);
            exit(1);
        }
    };

    if config.scripts.contains_key(&to_alias) && !force {
        println!("error: AliasAlreadyExists:  {}", to_alias);
        exit(1);
    }

    if let Some(script) = config.scripts.remove(&from_alias) {
        config.scripts.insert(to_alias.clone(), script);

        if let Err(e) = save_config(config_path, &config) {
            println!("error: {}", e);
            exit(1);
        }
        println!("Move from alias {} to new alias {}", from_alias, to_alias);
    } else {
        println!("error: AliasNotFound: No script found by alias {}", from_alias);
        exit(1);
    }
}

fn cmd_edit(config_path: &Path, matches: &ArgMatches) {
    let alias = matches.value_of("alias").unwrap();

    let config = match load_config(config_path) {
        Ok(c) => c,
        Err(e) => {
            println!("error: {}", e);
            exit(1);
        }
    };

    if config.scripts.contains_key(alias) {
        // For now, just fail since we need to handle editor interaction
        println!("error: EditorError: Failed when trying to get input from editor Failed to open `vi` as a text editor or editor was terminated with errors.");
        exit(1);
    } else {
        println!("error: AliasNotFound: No script found by alias {}", alias);
        exit(1);
    }
}

fn cmd_config_init(config_path: &Path) {
    // Create parent directory if needed
    if let Some(parent) = config_path.parent() {
        if !parent.exists() {
            if let Err(e) = fs::create_dir_all(parent) {
                println!("error: Failed to create directory. {}", e);
                exit(1);
            }
        }
    }

    // Create empty config
    let config = Config::default();
    if let Err(e) = save_config(config_path, &config) {
        println!("error: {}", e);
        exit(1);
    }
}
