            return Ok(p);
        }

        // Check $HOME/.pier
        let p = home_path.join(".pier");
        if p.exists() {
            return Ok(p);
        }
    }

    Err("No default config file found. See help for more info.".to_string())
}

fn load_config(config_path: &Path) -> Result<Config, String> {
    let content = fs::read_to_string(config_path)
        .map_err(|e| format!("Failed to read config: {}", e))?;
    parse_toml(&content)
}

fn save_config(config_path: &Path, config: &Config) -> Result<(), String> {
    let content = serialize_toml(config);
    fs::write(config_path, content)
        .map_err(|e| format!("Failed to write config: {}", e))
}

