struct Args {
    config_path: Option<String>,
    verbose: bool,
    command: Option<String>,
    rest: Vec<String>,
}

fn parse_args() -> Args {
    let args: Vec<String> = env::args().collect();
    let mut config_path = None;
    let mut verbose = false;
    let mut command = None;
    let mut rest = Vec::new();
    let mut skip_next = false;

    let mut i = 1;
    while i < args.len() {
        if skip_next {
            skip_next = false;
            i += 1;
            continue;
        }

        let arg = &args[i];

        if arg == "--help" || arg == "-h" {
            print_help();
            exit(0);
        } else if arg == "--version" || arg == "-V" {
            print_version();
            exit(0);
        } else if arg == "--verbose" || arg == "-v" {
            verbose = true;
        } else if arg == "--config-file" || arg == "-c" {
            if i + 1 < args.len() {
                config_path = Some(args[i + 1].clone());
                i += 1;
            }
        } else if arg.starts_with("--config-file=") {
            config_path = Some(arg[14..].to_string());
        } else if arg.starts_with("-c=") || arg.starts_with("--config-file=") {
            config_path = Some(arg.split('=').nth(1).unwrap().to_string());
        } else if !arg.starts_with('-') {
            // First non-flag argument is the command
            if command.is_none() {
                command = Some(arg.clone());
            } else {
                rest.push(arg.clone());
            }
        }

        i += 1;
    }

    Args {
        config_path,
        verbose,
        command,
        rest,
    }
}

