        let mut full_cmd = script.command.clone();
        for arg in run_args {
            full_cmd.push(' ');
            full_cmd.push_str(arg);
        }

        cmd.arg(&full_cmd);

        let status = cmd.status();
        match status {
            Ok(status) => {
                if !status.success() {
