        exit(1);
    }
}

fn cmd_show(config_path: &Path, args: &[String]) {
    if args.is_empty() {
        print_show_help();
        exit(1);
    }

    if args[0] == "--help" || args[0] == "-h" {
        print_show_help();
        exit(0);
    }

    if args[0] == "--version" || args[0] == "-V" {
        print_version();
        exit(0);
