use std::collections::BTreeMap;
use std::env;

// Simple TOML parser
#[derive(Debug, Clone)]
struct Script {
    command: String,
    description: Option<String>,
    tags: Vec<String>,
}

#[derive(Debug)]
struct Config {
    scripts: BTreeMap<String, Script>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
            scripts: BTreeMap::new(),
        }
    }
}

// Simple TOML parser - only handles our specific format
fn parse_toml(content: &str) -> Result<Config, String> {
    let mut config = Config::default();
    let mut current_alias: Option<String> = None;
    let mut current_script = Script {
        command: String::new(),
        description: None,
        tags: Vec::new(),
    };

    for line in content.lines() {
        let line = line.trim();

        // Skip empty lines and comments
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        // Check for section header [scripts.alias]
        if line.starts_with("[scripts.") && line.ends_with("]") {
            // Save previous script if exists
            if let Some(alias) = current_alias.take() {
                config.scripts.insert(alias, current_script.clone());
            }

            let alias = line[9..line.len()-1].to_string();
            current_alias = Some(alias);
            current_script = Script {
                command: String::new(),
                description: None,
                tags: Vec::new(),
            };
        } else if line.starts_with("[") {
            // Other section, save current script
            if let Some(alias) = current_alias.take() {
                config.scripts.insert(alias, current_script.clone());
            }
            current_script = Script {
                command: String::new(),
                description: None,
                tags: Vec::new(),
            };
        } else if current_alias.is_some() {
            // Parse key = value
            if let Some(eq_pos) = line.find('=') {
                let key = line[..eq_pos].trim();
                let value = line[eq_pos+1..].trim();

                if key == "command" {
                    // Remove quotes
                    let cmd = if (value.starts_with('"') && value.ends_with('"')) ||
                               (value.starts_with('\'') && value.ends_with('\'')) {
                        value[1..value.len()-1].to_string()
                    } else {
                        value.to_string()
                    };
                    current_script.command = cmd;
                } else if key == "description" {
                    let desc = if (value.starts_with('"') && value.ends_with('"')) ||
                                 (value.starts_with('\'') && value.ends_with('\'')) {
                        value[1..value.len()-1].to_string()
                    } else {
                        value.to_string()
                    };
                    current_script.description = Some(desc);
                } else if key == "tags" {
                    // Parse array
                    if value.starts_with('[') && value.ends_with(']') {
                        let tags_str = &value[1..value.len()-1];
                        for tag in tags_str.split(',') {
                            let tag = tag.trim();
                            let tag = if (tag.starts_with('"') && tag.ends_with('"')) ||
                                        (tag.starts_with('\'') && tag.ends_with('\'')) {
                                tag[1..tag.len()-1].to_string()
                            } else {
                                tag.to_string()
                            };
                            if !tag.is_empty() {
                                current_script.tags.push(tag);
                            }
                        }
                    }
                }
            }
        }
    }

    // Save last script
    if let Some(alias) = current_alias {
        config.scripts.insert(alias, current_script);
    }

    Ok(config)
}

fn serialize_toml(config: &Config) -> String {
    let mut result = String::new();

    for (alias, script) in &config.scripts {
        result.push_str(&format!("[scripts.{}]\n", alias));
        result.push_str(&format!("command = '{}'\n", escape_toml_string(&script.command)));

        if let Some(desc) = &script.description {
            result.push_str(&format!("description = '{}'\n", escape_toml_string(desc)));
        }

        if !script.tags.is_empty() {
            result.push_str("tags = [");
            for (i, tag) in script.tags.iter().enumerate() {
                if i > 0 {
                    result.push_str(", ");
                }
                result.push_str(&format!("'{}'", escape_toml_string(tag)));
            }
            result.push_str("]\n");
        }

        result.push('\n');
    }

    result.push_str("[default]\n");
    result
}

fn escape_toml_string(s: &str) -> String {
    s.replace('\\', "\\\\")
        .replace('\'', "\\'")
        .replace('\n', "\\n")
        .replace('\r', "\\r")
}

fn find_config_file() -> Result<PathBuf, String> {
    // Check PIER_CONFIG_PATH environment variable
    if let Ok(path) = env::var("PIER_CONFIG_PATH") {
        if !path.is_empty() {
            let p = PathBuf::from(path);
            if p.exists() {
                return Ok(p);
            }
        }
    }

    // Check pier.toml in current directory
    if let Ok(cwd) = env::current_dir() {
        let p = cwd.join("pier.toml");
        if p.exists() {
            return Ok(p);
        }
    }

    // Check XDG_CONFIG_HOME
    if let Ok(xdg_config) = env::var("XDG_CONFIG_HOME") {
        if !xdg_config.is_empty() {
            let xdg_path = PathBuf::from(&xdg_config);

            let p = xdg_path.join("pier").join("config.toml");
            if p.exists() {
                return Ok(p);
            }

            let p = xdg_path.join("pier").join("config");
            if p.exists() {
                return Ok(p);
            }

            let p = xdg_path.join("pier.toml");
            if p.exists() {
                return Ok(p);
            }
        }
    }

    // Check $HOME/.config/pier (default XDG location)
    if let Ok(home) = env::var("HOME") {
        let home_path = PathBuf::from(&home);
        let xdg_default = home_path.join(".config");

        let p = xdg_default.join("pier").join("config.toml");
        if p.exists() {
            return Ok(p);
        }

        let p = xdg_default.join("pier").join("config");
        if p.exists() {
            return Ok(p);
        }

        let p = xdg_default.join("pier.toml");
        if p.exists() {
            return Ok(p);
        }

        // Check $HOME/.pier.toml
        let p = home_path.join(".pier.toml");
        if p.exists() {
            return Ok(p);
        }

        // Check $HOME/.pier
        let p = home_path.join(".pier");
        if p.exists() {
            return Ok(p);
        }
    }

    Err("No default config file found. See help for more info.".to_string())
}

fn load_config(config_path: &Path) -> Result<Config, String> {
    let content = fs::read_to_string(config_path)
        .map_err(|e| format!("Failed to read config: {}", e))?;
    parse_toml(&content)
}

fn save_config(config_path: &Path, config: &Config) -> Result<(), String> {
    let content = serialize_toml(config);
    fs::write(config_path, content)
        .map_err(|e| format!("Failed to write config: {}", e))
}

