struct Args {
    config_path: Option<String>,
    rest: Vec<String>,
}

fn parse_global_args() -> Args {
    let args: Vec<String> = env::args().collect();
    let mut config_path = None;
    let mut rest = Vec::new();

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];

        if arg == "--help" || arg == "-h" {
            print_help();
            exit(0);
        } else if arg == "--version" || arg == "-V" {
            print_version();
            exit(0);
        } else if arg == "--config-file" || arg == "-c" {
            // Only consume if the next arg looks like a path (not a number for cmd_width)
            if i + 1 < args.len() {
                let next_arg = &args[i + 1];
                // If next arg is a number or a flag, don't consume it as config file
                if next_arg.starts_with('/') || next_arg.starts_with('.') || 
                   (!next_arg.starts_with('-') && !next_arg.chars().all(|c| c.is_numeric())) {
                    config_path = Some(next_arg.clone());
                    i += 1;
                }
            }
        } else if arg.starts_with("--config-file=") {
            config_path = Some(arg[14..].to_string());
        } else {
            // Everything else goes to the command and its args
            rest.push(arg.clone());
        }

        i += 1;
    }

    Args {
        config_path,
        rest,
    }
}

fn main() {
    let parsed = parse_global_args();

    let config_path = if let Some(path) = parsed.config_path {
        PathBuf::from(path)
    } else {
