use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, exit};
use std::collections::BTreeMap;
use std::env;

// Simple TOML parser
#[derive(Debug, Clone)]
struct Script {
    command: String,
    description: Option<String>,
    tags: Vec<String>,
}

#[derive(Debug)]
struct Config {
    scripts: BTreeMap<String, Script>,
}

impl Default for Config {
    fn default() -> Self {
        Config {
