    -V, --version    Prints version information

ARGS:
    <from-alias>    The alias of the script that will be moved.
    <to-alias>      The new alias of the script."#;
    println!("{}", help_text);
}

fn print_edit_help() {
    let help_text = r#"executable-edit 0.1.6
Edit a script matching alias.

USAGE:
    executable edit <alias>

FLAGS:
    -h, --help       Prints help information
    -V, --version    Prints version information

ARGS:
    <alias>    The alias or name for the script."#;
    println!("{}", help_text);
}

struct Args {
    config_path: Option<String>,
    rest: Vec<String>,
}

fn parse_global_args() -> Args {
    let args: Vec<String> = env::args().collect();
    let mut config_path = None;
    let mut rest = Vec::new();

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];

        if arg == "--help" || arg == "-h" {
            print_help();
            exit(0);
        } else if arg == "--version" || arg == "-V" {
            print_version();
            exit(0);
        } else if arg.starts_with("--config-file=") {
            config_path = Some(arg[14..].to_string());
            i += 1;
        } else if arg == "--config-file" || arg == "-c" {
            if i + 1 < args.len() {
                config_path = Some(args[i + 1].clone());
                i += 2;
            } else {
                i += 1;
            }
        } else {
            // Stop processing global flags and collect everything else as rest
            rest.push(arg.clone());
            i += 1;
            // Collect all remaining arguments
            while i < args.len() {
                rest.push(args[i].clone());
                i += 1;
            }
            break;
        }
    }

    Args {
        config_path,
        rest,
    }
}

fn main() {
    let parsed = parse_global_args();

    let config_path = if let Some(path) = parsed.config_path {
        PathBuf::from(path)
    } else {
        match find_config_file() {
            Ok(path) => path,
            Err(e) => {
                println!("error: {}", e);
                exit(1);
            }
        }
    };

    if parsed.rest.is_empty() {
        print_help();
        return;
    }

    let cmd = &parsed.rest[0];
    let args = if parsed.rest.len() > 1 {
        &parsed.rest[1..]
    } else {
        &[]
    };

    match cmd.as_str() {
        "add" => cmd_add(&config_path, args),
        "list" | "ls" => cmd_list(&config_path, args),
        "run" => cmd_run(&config_path, args),
        "show" => cmd_show(&config_path, args),
        "remove" | "rm" => cmd_remove(&config_path, args),
        "copy" | "cp" => cmd_copy(&config_path, args),
        "move" | "mv" | "rename" => cmd_move(&config_path, args),
        "edit" => cmd_edit(&config_path, args),
        "config-init" | "init" => cmd_config_init(&config_path),
        "help" => print_help(),
        _ => {
            // Try to run as a script alias
            cmd_run_direct(&config_path, parsed.rest.as_slice());
        }
    }
}

fn parse_list_args(args: &[String]) -> (bool, bool, Option<usize>, Vec<String>) {
    let mut list_aliases = false;
    let mut cmd_full = false;
    let mut cmd_width = None;
    let mut tags = Vec::new();
    let mut i = 0;

    while i < args.len() {
        let arg = &args[i];

        if arg == "--help" || arg == "-h" {
            print_list_help();
            exit(0);
        } else if arg == "--version" || arg == "-V" {
            print_version();
            exit(0);
        } else if arg == "-q" || arg == "--list_aliases" {
            list_aliases = true;
        } else if arg == "-l" || arg == "--cmd_full" {
            cmd_full = true;
        } else if arg == "-c" || arg == "--cmd_width" {
            if i + 1 < args.len() {
                cmd_width = args[i + 1].parse().ok();
                i += 1;
            }
        } else if arg == "-t" || arg == "--tag" {
            if i + 1 < args.len() {
                tags.push(args[i + 1].clone());
                i += 1;
            }
        }

        i += 1;
    }

    (list_aliases, cmd_full, cmd_width, tags)
}

fn cmd_list(config_path: &Path, args: &[String]) {
    let (list_aliases, cmd_full, cmd_width, filter_tags) = parse_list_args(args);

    let config = match load_config(config_path) {
        Ok(c) => c,
        Err(e) => {
            println!("error: {}", e);
            exit(1);
        }
    };

    // Filter scripts
    let scripts: Vec<_> = config.scripts.iter()
        .filter(|(_, script)| {
            if filter_tags.is_empty() {
                true
            } else {
                filter_tags.iter().all(|tag| script.tags.contains(tag))
            }
        })
        .collect();

    if list_aliases {
        // Just list aliases
        for (alias, _) in scripts {
            println!("{}", alias);
        }
    } else {
        // Table view
        let mut rows = Vec::new();

        for (alias, script) in scripts {
            let tags_str = script.tags.join(", ");
            let cmd = if cmd_full {
                script.command.clone()
            } else if let Some(width) = cmd_width {
                if script.command.len() > width {
                    script.command[..width].to_string()
                } else {
                    script.command.clone()
                }
            } else {
                script.command.clone()
            };
            let desc = script.description.clone().unwrap_or_default();

            rows.push((alias.clone(), tags_str, cmd, desc));
        }

        if rows.is_empty() {
            return;
        }

        // Calculate column widths
        let mut alias_width = 5; // "Alias"
        let mut tags_width = 4;  // "Tags"
        let mut cmd_width_calc = 7;   // "Command"
        let mut desc_width = 11; // "Description"

        for (alias, tags, cmd, desc) in &rows {
            alias_width = alias_width.max(alias.len());
            tags_width = tags_width.max(tags.len());
            cmd_width_calc = cmd_width_calc.max(cmd.len());
            desc_width = desc_width.max(desc.len());
        }

        // Print table
        let border = "≖".repeat(alias_width + tags_width + cmd_width_calc + desc_width + 11);
        println!("{}", border);

        // Header
        print!("⋮ {:<width1$} ⋮ {:<width2$} ⋮ {:<width3$} ⋮ {:<width4$} ⋮", 
            "Alias", "Tags", "Command", "Description",
            width1 = alias_width,
            width2 = tags_width,
            width3 = cmd_width_calc,
            width4 = desc_width);
        println!();

        println!("{}", border);

        // Data rows
        for (alias, tags, cmd, desc) in rows {
            print!("⋮ {:<width1$} ⋮ {:<width2$} ⋮ {:<width3$} ⋮ {:<width4$} ⋮",
                alias, tags, cmd, desc,
                width1 = alias_width,
                width2 = tags_width,
                width3 = cmd_width_calc,
                width4 = desc_width);
            println!();
        }

        println!("{}", border);
    }
}

fn parse_add_args(args: &[String]) -> (Option<String>, Option<String>, Vec<String>, bool, Option<String>) {
    let mut alias = None;
    let mut description = None;
    let mut tags = Vec::new();
    let mut force = false;
    let mut command = None;
    let mut i = 0;

    while i < args.len() {
        let arg = &args[i];

        if arg == "--help" || arg == "-h" {
            print_add_help();
            exit(0);
        } else if arg == "--version" || arg == "-V" {
            print_version();
            exit(0);
        } else if arg == "-f" || arg == "--force" {
            force = true;
        } else if arg == "-a" || arg == "--alias" {
            if i + 1 < args.len() {
                alias = Some(args[i + 1].clone());
                i += 1;
            }
        } else if arg == "-d" || arg == "--description" {
            if i + 1 < args.len() {
                description = Some(args[i + 1].clone());
                i += 1;
            }
        } else if arg == "-t" || arg == "--tag" {
            if i + 1 < args.len() {
                tags.push(args[i + 1].clone());
                i += 1;
            }
        } else if arg == "--" {
            // Everything after -- is the command
            if i + 1 < args.len() {
                command = Some(args[i + 1..].join(" "));
            }
            break;
        } else if !arg.starts_with('-') && command.is_none() {
            command = Some(arg.clone());
        }

        i += 1;
    }

    (alias, description, tags, force, command)
}

fn cmd_add(config_path: &Path, args: &[String]) {
    let (alias, description, tags, force, command) = parse_add_args(args);

    let alias = match alias {
        Some(a) => a,
        None => {
            println!("error: --alias is required");
            exit(1);
        }
    };

    let command = match command {
        Some(c) => c,
        None => {
            println!("error: EditorError: Failed when trying to get input from editor Failed to open `vi` as a text editor or editor was terminated with errors.");
            exit(1);
        }
    };

    let mut config = match load_config(config_path) {
        Ok(c) => c,
        Err(e) => {
            println!("error: {}", e);
            exit(1);
        }
    };

    if config.scripts.contains_key(&alias) && !force {
        println!("error: AliasAlreadyExists:  {}", alias);
        exit(1);
    }

    config.scripts.insert(alias.clone(), Script {
        command,
        description,
        tags,
    });

    if let Err(e) = save_config(config_path, &config) {
        println!("error: {}", e);
        exit(1);
    }

    println!("Added {}", alias);
}

fn cmd_run(config_path: &Path, args: &[String]) {
    if args.is_empty() {
        print_run_help();
        exit(1);
    }

    if args[0] == "--help" || args[0] == "-h" {
        print_run_help();
        exit(0);
    }

    if args[0] == "--version" || args[0] == "-V" {
        print_version();
        exit(0);
    }

    let alias = &args[0];
    let run_args = if args.len() > 1 { &args[1..] } else { &[] };

    let config = match load_config(config_path) {
        Ok(c) => c,
        Err(e) => {
            println!("error: {}", e);
            exit(1);
        }
    };

    if let Some(script) = config.scripts.get(alias) {
        let mut cmd = Command::new("sh");
        cmd.arg("-c");

        let mut full_cmd = script.command.clone();
        for arg in run_args {
            full_cmd.push(' ');
            full_cmd.push_str(arg);
        }

        cmd.arg(&full_cmd);

        let status = cmd.status();
        match status {
            Ok(status) => {
                if !status.success() {
                    exit(status.code().unwrap_or(1));
                }
            }
            Err(e) => {
                println!("error: Failed to execute script: {}", e);
                exit(1);
            }
        }
    } else {
        println!("error: AliasNotFound: No script found by alias {}", alias);
        exit(1);
    }
}

