    } else {
        println!("error: AliasNotFound: No script found by alias {}", from_alias);
        exit(1);
    }
}

fn parse_move_args(args: &[String]) -> (Option<String>, Option<String>, bool) {
    let mut from_alias = None;
    let mut to_alias = None;
    let mut force = false;
    let mut i = 0;

    while i < args.len() {
        let arg = &args[i];

        if arg == "--help" || arg == "-h" {
            print_move_help();
            exit(0);
        } else if arg == "--version" || arg == "-V" {
            print_version();
            exit(0);
        } else if arg == "-f" || arg == "--force" {
            force = true;
        } else if !arg.starts_with('-') {
            if from_alias.is_none() {
                from_alias = Some(arg.clone());
            } else if to_alias.is_none() {
                to_alias = Some(arg.clone());
            }
        }

        i += 1;
    }

    (from_alias, to_alias, force)
}

fn cmd_move(config_path: &Path, args: &[String]) {
    let (from_alias, to_alias, force) = parse_move_args(args);

    let from_alias = match from_alias {
        Some(a) => a,
        None => {
            print_move_help();
            exit(1);
        }
    };

    let to_alias = match to_alias {
        Some(a) => a,
        None => {
            print_move_help();
            exit(1);
        }
    };

    let mut config = match load_config(config_path) {
        Ok(c) => c,
        Err(e) => {
            println!("error: {}", e);
            exit(1);
        }
    };

    if config.scripts.contains_key(&to_alias) && !force {
        println!("error: AliasAlreadyExists:  {}", to_alias);
        exit(1);
    }

    if let Some(script) = config.scripts.remove(&from_alias) {
        config.scripts.insert(to_alias.clone(), script);

        if let Err(e) = save_config(config_path, &config) {
            println!("error: {}", e);
            exit(1);
        }
        println!("Move from alias {} to new alias {}", from_alias, to_alias);
    } else {
        println!("error: AliasNotFound: No script found by alias {}", from_alias);
        exit(1);
    }
}

